"""Draft for Selective Compulsory Book 3, Chapters 4–5 (People's Education Press, 2019): atomic structure, wave-particle duality, and the atomic nucleus."""
from phy_hs_lib import T, C, N

# ---------------- Chapter 4: Atomic Structure and Wave-Particle Duality
T("blackbody", "Matter", "conceptual",
  "Understand blackbodies and the experimental laws of blackbody radiation: as temperature rises, radiation intensity increases at every wavelength, and the peak shifts toward shorter wavelengths. Know Planck's energy-quantum hypothesis: energy can be emitted or absorbed only in integer multiples of ε = hν. Understand that energy quanta introduced the idea of quantization in the microscopic world.",
  ["State the experimental laws of blackbody radiation", "Describe the energy-quantum hypothesis", "Calculate the energy of one quantum using ε = hν"],
  [("S3.4.2", "exact"), ("S3.4.1", "inferred")],
  pre=[("quantum", "hard"), ("em_spectrum", "soft"), ("temperature", "soft")],
  qs=[
    C("basic", "Planck proposed the energy-quantum hypothesis to explain the experimental laws of blackbody radiation. Which statement describes the hypothesis correctly?",
      "Energy is emitted or absorbed in discrete amounts, each an integer multiple of the minimum quantum ε = hν",
      ["Energy can take any continuous value; radiation intensity depends only on temperature, not frequency",
       "Each quantum of energy ε is proportional to light intensity and independent of frequency",
       "The quantum energy is ε = h/ν, so each quantum is smaller at higher frequencies"],
      "The energy-quantum hypothesis states that a charged particle can emit or absorb energy only in integer multiples of a minimum value, ε = hν, which is proportional to frequency. Classical theory treated energy as continuous and therefore could not explain blackbody radiation."),
    N("basic", "For light with frequency 1.0×10¹⁵ Hz, what is the energy ε of one photon (energy quantum), in units of 10⁻¹⁹ J? (h = 6.63×10⁻³⁴ J·s; enter the number only.)", "6.63",
      "ε = hν = 6.63×10⁻³⁴ × 1.0×10¹⁵ J = 6.63×10⁻¹⁹ J. Using ε = h/ν instead would give a completely different order of magnitude.",
      "round(6.63e-34*1.0e15/1e-19,2)"),
    C("standard", "As the temperature of a blackbody rises, which statement about the experimental laws of blackbody radiation is correct?",
      "Radiation intensity increases at every wavelength, and the peak shifts toward shorter wavelengths",
      ["Radiation intensity increases at every wavelength, and the peak shifts toward longer wavelengths",
       "Only the long-wavelength intensity increases, while the peak stays in the same place",
       "Radiation intensity decreases at every wavelength, and the peak shifts toward shorter wavelengths"],
      "As temperature rises, radiation intensity increases at every wavelength, and the peak shifts toward shorter wavelengths (higher frequencies). This is why a heated object changes in color from dull red to orange-yellow and then to white-hot."),
    N("standard", "A light source emits monochromatic light at 1.0×10¹⁵ Hz with a radiant power of 1.326 W. How many photons does it emit each second, in units of 10¹⁸? (h = 6.63×10⁻³⁴ J·s; enter the number only.)", "2",
      "Each photon has energy ε = hν = 6.63×10⁻¹⁹ J. The number emitted per second is n = P/ε = 1.326 ÷ 6.63×10⁻¹⁹ = 2.0×10¹⁸ photons.",
      "round(1.326/(6.63e-34*1.0e15)/1e18,2)"),
  ])

T("photoelectric", "Matter", "conceptual",
  "Understand the photoelectric effect from experiments: electrons are emitted when light strikes a metal. There is a cutoff frequency; below it, the effect does not occur regardless of light intensity or exposure time. The maximum kinetic energy of photoelectrons is independent of intensity, saturation photocurrent increases with intensity, and emission is nearly instantaneous.",
  ["State the four experimental laws of the photoelectric effect", "Distinguish the effects of light intensity and frequency", "Estimate the number of photoelectrons emitted per unit time from the saturation photocurrent"],
  [("S3.4.1", "exact"), ("S3.4.2", "inferred")],
  pre=[("blackbody", "hard"), ("potential_diff", "soft"), ("em_wave", "soft")],
  qs=[
    C("basic", "A certain monochromatic light shines on a metal surface, but no photoelectrons are emitted. Which change could make the photoelectric effect occur?",
      "Use light with a higher frequency", ["Increase the intensity of the same light", "Increase the exposure time", "Increase the illuminated area"],
      "The photoelectric effect occurs only when the incident-light frequency exceeds the metal's cutoff frequency. It does not depend on intensity, exposure time, or illuminated area; only higher-frequency light could meet the condition."),
    C("basic", "A phototube is illuminated by monochromatic light above its cutoff frequency. If the frequency stays constant while the light intensity increases, how do the saturation photocurrent and stopping potential change?",
      "The saturation photocurrent increases, while the stopping potential stays the same", ["The saturation photocurrent stays the same, while the stopping potential increases", "Both the saturation photocurrent and stopping potential increase", "Both the saturation photocurrent and stopping potential stay the same"],
      "Greater intensity means more photons strike the metal per unit time, so more photoelectrons are emitted and the saturation photocurrent increases. Maximum photoelectron kinetic energy depends only on frequency, so the stopping potential is unchanged."),
    C("standard", "Which statement about the experimental laws of the photoelectric effect is correct?",
      "The maximum kinetic energy of photoelectrons increases with incident-light frequency and is independent of intensity",
      ["Stronger incident light gives photoelectrons greater maximum kinetic energy",
       "Any frequency of light will cause the photoelectric effect if the exposure lasts long enough",
       "Photoelectrons are emitted only after several seconds of energy accumulation"],
      "Maximum photoelectron kinetic energy depends only on incident-light frequency. Light below the cutoff frequency cannot produce the effect no matter how long it shines, and emission is nearly instantaneous (within about 10⁻⁹ s); there is no energy-accumulation delay. Classical wave theory could not explain these results."),
    N("standard", "A phototube operates at saturation with a photocurrent of 3.2 μA. Assume all photoelectrons reach the anode. The electron charge is e = 1.6×10⁻¹⁹ C. How many photoelectrons are emitted by the cathode each second, in units of 10¹³? (Enter the number only.)", "2",
      "At saturation, the number reaching the anode each second is n = I/e = 3.2×10⁻⁶ ÷ 1.6×10⁻¹⁹ = 2.0×10¹³. Convert μA to A (10⁻⁶ A); omitting this conversion gives an error by a factor of 10⁶.",
      "round(3.2e-6/1.6e-19/1e13,2)"),
  ])

T("einstein_photo", "Matter", "procedural",
  "Understand Einstein's photoelectric equation, Ek = hν − W0: one electron absorbs a photon's energy at once; part overcomes the work function, and the rest becomes the photoelectron's maximum kinetic energy. The stopping potential satisfies Uc·e = Ek. Analyze the slope and intercept of an Ek−ν graph.",
  ["Use Ek = hν − W0 to calculate maximum kinetic energy and cutoff frequency (or wavelength)", "Find the stopping potential from Uc·e = Ek", "Read h, W0, and the cutoff frequency from an Ek−ν graph"],
  [("S3.4.1", "exact")],
  pre=[("photoelectric", "hard"), ("work_energy_theorem", "hard"), ("blackbody", "soft")],
  math=[("cnm_202", "An Ek−ν graph is a straight line with slope h and an intercept related to the work function; interpreting it requires reading a linear-function graph.")],
  qs=[
    N("basic", "A metal has a work function of 2.3 eV and is illuminated by photons with energy 4.1 eV. What is the maximum kinetic energy of the emitted photoelectrons in eV? (Enter the number only.)", "1.8",
      "Ek = hν − W0 = 4.1 eV − 2.3 eV = 1.8 eV. Using Ek = hν + W0 would incorrectly give 6.4 eV.",
      "round(4.1-2.3,2)"),
    C("basic", "A metal with a work function of 2.0 eV is illuminated by photons with energy 3.5 eV. What is the stopping potential?",
      "1.5 V", ["3.5 V", "5.5 V", "2.0 V"],
      "The maximum kinetic energy is Ek = 3.5 eV − 2.0 eV = 1.5 eV. From Uc·e = Ek, Uc = 1.5 V. 3.5 V forgets to subtract the work function; 2.0 V mistakes the work function for the stopping potential.",
      verify="3.5-2.0"),
    N("standard", "A metal has a work function of 2.48 eV. What is its cutoff wavelength in nm? (hc = 1240 eV·nm; enter the number only.)", "500",
      "At the cutoff frequency, hν0 = W0, so hc/λ0 = W0 and λ0 = hc/W0 = 1240 ÷ 2.48 nm = 500 nm. Light with a wavelength shorter than 500 nm can produce the photoelectric effect; do not reverse the inequality.",
      "round(1240/2.48,1)"),
    C("advanced", "The maximum photoelectron kinetic energy Ek is plotted against incident-light frequency ν for metals A and B. Both graphs are straight lines, and metal A has the greater work function. Which statement about the graphs is correct?",
      "The graphs are parallel, and metal A has the larger x-intercept (cutoff frequency)",
      ["The graphs are parallel, and metal A has the smaller x-intercept (cutoff frequency)",
       "Metal A's graph has a steeper slope, and the graphs intersect above the x-axis",
       "The slope equals the work function, so metal A's graph has a steeper slope"],
      "From Ek = hν − W0, the slope is h for every metal, so the graphs are parallel. The x-intercept is ν0 = W0/h; a larger W0 means a larger cutoff frequency, so metal A's intercept is larger. The absolute value of the y-intercept equals the work function."),
  ])

T("rutherford", "Matter", "conceptual",
  "Understand the setup and observations of the α-particle scattering experiment: most α particles pass through gold foil almost undeflected, a few are deflected through large angles, and very few are deflected by more than 90°. These results led to the nuclear model of the atom: a tiny nucleus at the center contains all the positive charge and nearly all the mass.",
  ["Describe the observations of the α-particle scattering experiment", "Describe the nuclear model of the atom", "Use Coulomb force to explain large-angle deflection and estimate the distance of closest approach"],
  [("S3.3.1", "exact"), ("S3.3.5", "inferred")],
  pre=[("coulomb", "hard"), ("J:charge", "soft"), ("charge", "soft")],
  qs=[
    C("basic", "In the α-particle scattering experiment, α particles were directed at a very thin sheet of gold foil. What was observed?",
      "Most α particles passed through almost undeflected, a few were deflected through large angles, and very few bounced back",
      ["All α particles were deflected through large angles", "Most α particles bounced back from the gold foil", "All α particles passed straight through without any deflection"],
      "The fact that most particles were barely deflected shows that most of the atom is empty space. The few large deflections, and especially the rare particles that bounced back, show that the atom has a tiny, massive, positively charged nucleus."),
    C("basic", "Which statement describes the nuclear model of the atom proposed by Rutherford from the α-particle scattering results?",
      "All positive charge and nearly all the mass are concentrated in a tiny nucleus, with electrons moving around it",
      ["Positive charge is spread uniformly throughout a spherical atom, with electrons embedded in it",
       "Most of the atom's mass is in the electrons outside the nucleus, which carries little charge",
       "The nucleus contains only protons, while electrons and neutrons orbit outside it"],
      "The model with positive charge spread uniformly and electrons embedded in it is Thomson's “plum-pudding model,” which the scattering results contradicted. The nuclear model places a tiny nucleus at the center, containing nearly all the atom's mass and all its positive charge, with electrons outside it."),
    C("standard", "What is the main reason a few α particles are deflected through large angles in the scattering experiment?",
      "An α particle experiences strong Coulomb repulsion when it approaches the nucleus",
      ["An α particle collides with an electron outside the nucleus and changes direction", "An α particle is acted on by the gravitational force of the nucleus", "An α particle is deflected because it is attracted to the gold nucleus"],
      "An electron has only about one seven-thousandth the mass of an α particle, so collisions with electrons have almost no effect on its motion. Both α particles and nuclei are positively charged, so strong Coulomb repulsion at close range can produce large-angle deflection. Gravity is negligible compared with the Coulomb force."),
    N("advanced", "An α particle (charge number 2) with kinetic energy 7.2 MeV is directed head-on at a stationary target nucleus with charge number Z = 50, which is treated as fixed. At the closest approach, all kinetic energy has been converted to electric potential energy. Given ke² = 1.44 MeV·fm (k is the electrostatic constant, e the elementary charge, and 1 fm = 10⁻¹⁵ m), what is the closest distance in fm? (Enter the number only.)", "20",
      "By energy conservation, Ek = k·(2e)(Ze)/r = 2Z·ke²/r, so r = 2Z·ke²/Ek = 2×50×1.44 ÷ 7.2 fm = 20 fm. Omitting the α particle's charge number 2 would give 10 fm.",
      "round(2*50*1.44/7.2,2)"),
  ])

T("hydrogen_spectrum", "Matter", "conceptual",
  "Know that the hydrogen spectrum is a line spectrum made up of discrete bright lines, and that each element has its own characteristic spectral lines that can be used for spectroscopic analysis. Understand the Balmer formula 1/λ = R(1/2² − 1/n²) (n = 3, 4, 5, …), and know that classical electromagnetic theory cannot explain the discrete nature of atomic spectra.",
  ["Distinguish continuous spectra from line spectra", "Compare spectral-line wavelengths using the Balmer formula", "Explain the principle of spectroscopic analysis"],
  [("S3.3.1", "exact")],
  pre=[("rutherford", "hard"), ("em_spectrum", "soft"), ("J:dispersion", "soft")],
  qs=[
    C("basic", "What spectrum is produced when light from a low-pressure hydrogen discharge passes through a prism or diffraction grating?",
      "A line spectrum made up of discrete bright lines", ["A continuous spectrum from red to violet", "An absorption spectrum with dark lines on a continuous background", "A monochromatic spectrum with just one bright line"],
      "Light from a low-pressure gas produces a line (bright-line) spectrum. Hydrogen's spectrum consists of discrete bright lines at specific wavelengths; continuous spectra come from hot solids or liquids."),
    C("basic", "According to the Balmer formula 1/λ = R(1/2² − 1/n²) (n = 3, 4, 5, …), which visible hydrogen spectral line has the longest wavelength?",
      "The line for n = 3", ["The line for n = 4", "The line as n approaches infinity", "All the lines have the same wavelength"],
      "As n increases, 1/2² − 1/n² and 1/λ increase, so the wavelength decreases. The expression in parentheses is smallest for n = 3, giving the longest wavelength; as n approaches infinity, the wavelength is shortest at the series limit."),
    N("standard", "Using the Balmer formula 1/λ = R(1/2² − 1/n²), what is the ratio λ₃/λ₄ between the wavelengths for n = 3 and n = 4? (Enter the number only.)", "1.35",
      "1/λ₃ = R(1/4 − 1/9) = 5R/36, and 1/λ₄ = R(1/4 − 1/16) = 3R/16. Thus λ₃/λ₄ = (3/16)/(5/36) = 27/20 = 1.35. Wavelength is inversely proportional to 1/λ; reversing the ratio would give 0.74.",
      "round((1/4-1/16)/(1/4-1/9),2)"),
    C("standard", "Which statement about spectra and spectroscopic analysis is correct?",
      "Each element has its own characteristic spectral lines, which can identify the elements in a substance",
      ["Hot solids produce line spectra that can identify elements",
       "Different elements have identical line spectra, so they cannot be distinguished",
       "The lines in a continuous spectrum are characteristic atomic lines that identify a substance"],
      "The line spectra of different elements are distinct and are called characteristic spectra, so spectroscopic analysis can identify a substance's composition. Hot solids produce continuous spectra, which do not contain element-specific lines."),
  ])

T("bohr", "Matter", "procedural",
  "Know the Bohr model: atoms can occupy only a discrete set of energy states (stationary states), and the hydrogen energy levels are E_n = −13.6 eV/n². A transition between levels emits or absorbs a photon, with hν = E_m − E_n. A group of hydrogen atoms in level n can emit at most n(n−1)/2 different photon frequencies.",
  ["Calculate a photon's energy during a transition from the energy-level formula", "Calculate the number of spectral lines emitted by a group of hydrogen atoms", "Analyze changes in kinetic, potential, and total energy during a transition"],
  [("S3.3.1", "exact"), ("S3.4.2", "inferred")],
  pre=[("hydrogen_spectrum", "hard"), ("einstein_photo", "soft"), ("potential", "soft"), ("coulomb", "soft")],
  qs=[
    N("basic", "The hydrogen energy levels are E_n = −13.6 eV/n². What is the energy, in eV, of the photon emitted when a hydrogen atom transitions from n = 2 to n = 1? (Enter the number only.)", "10.2",
      "E₂ = −3.4 eV and E₁ = −13.6 eV, so hν = E₂ − E₁ = −3.4 − (−13.6) = 10.2 eV. A transition from a higher to a lower level emits a photon with energy equal to the magnitude of the level difference.",
      "round(13.6*(1-1/4),2)"),
    N("basic", "A group of hydrogen atoms is in the excited state n = 5. What is the maximum number of different photon frequencies they can emit as they transition to lower levels? (Enter the number only.)", "10",
      "The maximum number is n(n−1)/2 = 5×4/2 = 10. Counting only the sequence 5→4→3→2→1 would incorrectly give 4.",
      "5*4//2"),
    C("standard", "A hydrogen atom transitions from n = 3 to n = 2. Which statement is correct?",
      "It emits a photon; the electron's kinetic energy increases, its potential energy decreases, and the atom's total energy decreases",
      ["It emits a photon; the electron's kinetic energy decreases, its potential energy increases, and the atom's total energy decreases",
       "It emits a photon; the electron's kinetic and potential energies both increase, while the atom's total energy decreases",
       "It absorbs a photon; the electron's kinetic energy decreases, its potential energy increases, and the atom's total energy increases"],
      "A transition from a higher to a lower level emits a photon and reduces the atom's total energy. The orbital radius decreases. Since the Coulomb force provides centripetal force, ke²/r² = mv²/r implies that kinetic energy increases. The electric force does positive work, so potential energy decreases by more than kinetic energy increases, and total energy decreases."),
    N("advanced", "A group of hydrogen atoms in the excited state n = 4 emits photons of different frequencies as it transitions to lower levels. These photons illuminate a metal with a work function of 2.25 eV. How many photon energies can produce the photoelectric effect? (E_n = −13.6 eV/n²; enter the number only.)", "4",
      "The six transition energies are: 4→3, 0.66 eV; 3→2, 1.89 eV; 4→2, 2.55 eV; 2→1, 10.2 eV; 3→1, 12.09 eV; and 4→1, 12.75 eV. Four are greater than 2.25 eV.",
      "sum(1 for a in range(2,5) for b in range(1,a) if 13.6*(1/b**2-1/a**2) > 2.25)"),
  ])

T("wave_particle", "Matter", "conceptual",
  "Know that light has both wave properties (interference and diffraction) and particle properties (the photoelectric effect), which is called wave-particle duality. Matter particles also have wave properties, with de Broglie wavelength λ = h/p; electron-diffraction experiments confirm this. Understand the difference between the behavior of many particles and that of individual particles.",
  ["Explain wave-particle duality of light", "Calculate de Broglie wavelength using λ = h/p", "Know that electron diffraction demonstrates the wave properties of matter"],
  [("S3.4.2", "exact"), ("S3.4.1", "exact")],
  pre=[("einstein_photo", "hard"), ("momentum", "hard"), ("diffraction", "soft"), ("potential_diff", "soft")],
  qs=[
    C("basic", "An electron and a proton have different masses but move at the same speed. Which statement about their de Broglie wavelengths is correct?",
      "The electron has the longer de Broglie wavelength", ["The proton has the longer de Broglie wavelength", "They have equal de Broglie wavelengths", "Only electrons have wave properties; protons are matter particles and have no de Broglie wavelength"],
      "λ = h/p = h/(mv). At the same speed, a smaller mass gives a smaller momentum and a longer wavelength. An electron is much less massive than a proton, so its de Broglie wavelength is longer. Electron diffraction has confirmed the wave properties of matter."),
    N("basic", "A particle has momentum 6.63×10⁻²⁴ kg·m/s. What is its de Broglie wavelength in pm? (h = 6.63×10⁻³⁴ J·s; 1 pm = 10⁻¹² m; enter the number only.)", "100",
      "λ = h/p = 6.63×10⁻³⁴ ÷ 6.63×10⁻²⁴ m = 1×10⁻¹⁰ m = 100 pm. This is comparable to the spacing between atoms, so a crystal can diffract an electron beam.",
      "round(6.63e-34/6.63e-24*1e12,2)"),
    N("standard", "An electron (mass m = 9.1×10⁻³¹ kg, charge e = 1.6×10⁻¹⁹ C) starts from rest and is accelerated through a potential difference of 150 V. What is its approximate de Broglie wavelength in pm? (h = 6.63×10⁻³⁴ J·s; round to the nearest integer and enter the number only.)", "100",
      "eU = p²/(2m), so p = √(2meU) = √(2×9.1×10⁻³¹×1.6×10⁻¹⁹×150) ≈ 6.61×10⁻²⁴ kg·m/s. Then λ = h/p ≈ 1.003×10⁻¹⁰ m ≈ 100 pm.",
      "round(6.63e-34/sqrt(2*9.1e-31*1.6e-19*150)*1e12)"),
    C("standard", "Which statement about wave-particle duality of light is correct?",
      "The behavior of many photons often shows wave properties, while individual photons often show particle properties",
      ["The higher the light frequency, the more evident its wave properties and the less evident its particle properties",
       "The photoelectric effect shows that light is a wave, while interference shows that it is a particle",
       "Light interference shows that light is a stream of rapidly moving particles"],
      "The photoelectric effect demonstrates particle properties, while interference and diffraction demonstrate wave properties. Higher-frequency, shorter-wavelength light shows more evident particle properties. Many photons behave like a wave, while individual photons behave like particles; interference cannot be explained by a classical stream of particles."),
  ])

# ---------------- Chapter 5: The Atomic Nucleus
T("radioactivity", "Matter", "conceptual",
  "Know that Becquerel's discovery of natural radioactivity showed that the nucleus has a complex internal structure. Know the nature of α, β, and γ rays (helium nuclei, electrons, and very short-wavelength electromagnetic waves), how they deflect in a magnetic field, and how their ionizing and penetrating powers compare.",
  ["Identify the nature of the three types of radiation", "Compare their ionizing and penetrating powers", "Determine how each type of radiation deflects in a magnetic field"],
  [("S3.3.3", "exact")],
  pre=[("rutherford", "hard"), ("lorentz_force", "soft"), ("J:charge", "soft")],
  qs=[
    C("basic", "What is the nature of the β rays emitted by naturally radioactive elements?",
      "A stream of high-speed electrons", ["A stream of helium nuclei", "A stream of high-speed protons", "High-frequency electromagnetic waves"],
      "α rays are streams of helium nuclei, β rays are streams of high-speed electrons, and γ rays are very short-wavelength electromagnetic waves (photons)."),
    C("basic", "Which of α, β, and γ rays has the greatest penetrating power and the weakest ionizing power?",
      "γ rays", ["α rays", "β rays", "All three have the same penetrating and ionizing powers"],
      "Penetrating power ranks γ > β > α, while ionizing power ranks α > β > γ. Paper blocks α rays; a few millimeters of aluminum can block β rays; several centimeters of lead can block γ rays."),
    C("standard", "Radiation from a naturally radioactive source enters upward into a uniform magnetic field directed into the page. Neglect gravity. How do α, β, and γ rays deflect, respectively?",
      "Left, right, and not at all", ["Right, left, and not at all", "Left, left, and not at all", "Left, right, and right"],
      "α rays are positively charged, β rays are negatively charged, and γ rays are neutral. A positive charge moving upward in a magnetic field into the page experiences a Lorentz force to the left, so α rays deflect left, β rays right, and γ rays do not deflect."),
    C("standard", "What did Becquerel's discovery of natural radioactivity demonstrate?",
      "The atomic nucleus has a complex internal structure", ["The atom has a nuclear structure", "Atomic energy is quantized", "Light has wave-particle duality"],
      "Radioactivity is the spontaneous emission of radiation from the nucleus, showing that the nucleus itself has internal structure. The nuclear model of the atom was established from the α-particle scattering experiment."),
  ])

T("nucleus_comp", "Matter", "conceptual",
  "Know that the nucleus consists of protons and neutrons (collectively called nucleons). The mass number A is the number of nucleons, the charge number Z is the number of protons, and the number of neutrons is A − Z. Isotopes have the same number of protons but different numbers of neutrons and nearly identical chemical properties.",
  ["Represent a nucleus using ᴬ_Z X notation and find its numbers of protons and neutrons", "Identify pairs of isotopes", "Explain mass number and charge number"],
  [("S3.3.2", "exact")],
  pre=[("rutherford", "hard"), ("radioactivity", "soft"), ("J:molecule", "soft")],
  qs=[
    N("basic", "A uranium nucleus ²³⁸₉₂U has mass number 238 and charge number 92. How many neutrons does it contain? (Enter the number only.)", "146",
      "Mass number A = number of protons + number of neutrons, so the neutron count is A − Z = 238 − 92 = 146. 92 is the number of protons (the charge number), not the number of neutrons.",
      "238-92"),
    C("basic", "Which pair of nuclei are isotopes?",
      "¹²₆C and ¹⁴₆C", ["¹⁴₆C and ¹⁴₇N", "¹H and ⁴₂He", "⁴⁰₁₈Ar and ⁴⁰₂₀Ca"],
      "Isotopes have the same number of protons (charge number) but different numbers of neutrons. Both ¹²₆C and ¹⁴₆C have charge number 6; the other pairs have different charge numbers. ¹⁴₆C and ¹⁴₇N, and ⁴⁰₁₈Ar and ⁴⁰₂₀Ca, merely have the same mass number."),
    N("standard", "An oxygen isotope is ¹⁶₈O. What is the charge of its nucleus in units of 10⁻¹⁹ C? (The elementary charge is e = 1.6×10⁻¹⁹ C; enter the number only.)", "12.8",
      "The nuclear charge is q = Ze = 8 × 1.6×10⁻¹⁹ C = 12.8×10⁻¹⁹ C. The charge number Z is the number of protons, not the mass number 16.",
      "round(8*1.6,2)"),
    C("standard", "Which statement about the uranium isotopes ²³⁵₉₂U and ²³⁸₉₂U is correct?",
      "They have the same number of protons, different numbers of neutrons, and nearly identical chemical properties",
      ["They have the same number of neutrons, different numbers of protons, and different chemical properties", "They have the same number of protons and mass number, so they are the same nucleus", "They have different numbers of electrons outside the nucleus, so their chemical properties differ"],
      "Both have charge number 92, but their neutron counts are 143 and 146. Chemical properties depend on the number of electrons; neutral atoms of both isotopes have 92 electrons, so their chemical properties are nearly identical."),
  ])

T("decay", "Matter", "procedural",
  "Know that radioactive decay is the spontaneous emission of an α or β particle from a nucleus, producing a new nucleus. Write α- and β-decay equations using conservation of mass number and charge number, and calculate the number of decays. Know that the electron emitted in β decay is produced when a neutron in the nucleus changes into a proton.",
  ["Write nuclear equations for α and β decay", "Calculate the number of decays", "Use momentum conservation to analyze the recoil after a stationary nucleus decays"],
  [("S3.3.2", "exact"), ("S3.3.3", "exact")],
  pre=[("nucleus_comp", "hard"), ("radioactivity", "hard"), ("momentum_conservation", "soft")],
  qs=[
    C("basic", "What nucleus is produced when ²³⁸₉₂U undergoes one α decay?",
      "²³⁴₉₀Th", ["²³⁴₉₂U", "²³⁸₉₃Np", "²³⁶₉₀Th"],
      "An α particle is ⁴₂He, so ²³⁸₉₂U → ²³⁴₉₀Th + ⁴₂He. The mass number decreases by 4 and the charge number by 2. ²³⁸₉₃Np is a product of β decay, which increases the charge number by 1."),
    C("basic", "Where does the electron emitted during β decay come from?",
      "It is produced when a neutron in the nucleus changes into a proton", ["It is an electron ionized from outside the nucleus", "It was already present inside the nucleus", "It is produced when a proton in the nucleus changes into a neutron"],
      "There are no electrons inside the nucleus. In β decay, a neutron changes into a proton and an electron; the electron is emitted as β radiation, so the charge number increases by 1 while the mass number stays the same."),
    N("standard", "After several α and β decays, ²³⁸₉₂U becomes stable ²⁰⁶₈₂Pb. How many β decays occur? (Enter the number only.)", "6",
      "The mass number decreases by 238 − 206 = 32. Only α decay changes mass number, so there are 32/4 = 8 α decays. These decrease the charge number by 16, but the actual decrease is only 92 − 82 = 10, so there must be 16 − 10 = 6 β decays.",
      "2*((238-206)//4)-(92-82)"),
    N("advanced", "A stationary ²³⁸₉₂U nucleus undergoes α decay. The emitted α particle moves at 5850 km/s in the positive x direction. Assume nuclear mass is proportional to mass number (use 4 for the α particle and 234 for the daughter nucleus). What is the magnitude of the daughter nucleus's recoil velocity in km/s? (Enter the number only.)", "100",
      "Momentum is conserved: 0 = 4·v_α − 234·v, so v = 4×5850/234 km/s = 100 km/s, in the negative x direction. The daughter nucleus has greater mass and lower speed; reversing the mass ratio would incorrectly make its speed greater than the α particle's.",
      "4*5850//234"),
  ])

T("half_life", "Matter", "procedural",
  "Know that the half-life is the time required for half the nuclei in a large sample of a radioactive substance to decay. The remaining amount is N = N₀(½)^(t/τ). Half-life is an intrinsic nuclear property, independent of temperature, pressure, and chemical state. It is a statistical law and has no meaning for a small number of nuclei.",
  ["Calculate the remaining amount using N = N₀(½)^(t/τ)", "Know that half-life is independent of external conditions", "Explain the statistical meaning of half-life"],
  [("S3.3.3", "exact")],
  pre=[("decay", "hard"), ("speed_distribution", "soft")],
  math=[("cnm_h041", "The remaining amount decreases exponentially with time: N = N₀(½)^(t/τ) is an exponential function with base ½."),
        ("cnm_h040", "When t/τ is not an integer, exponent rules are needed.")],
  qs=[
    N("basic", "A radioactive isotope has a half-life of 5 days. If there are 80 g initially, how many grams remain undecayed after 15 days? (Enter the number only.)", "10",
      "15 days is 3 half-lives, so N = 80 × (1/2)³ = 10 g. Treating the half-life as the time for all atoms to decay would give 0.",
      "80*(1/2)**3"),
    C("basic", "For a fixed amount of a radioactive isotope, what is the effect on its half-life of increasing temperature, increasing pressure, or causing a chemical reaction?",
      "None of these changes the half-life", ["Increasing temperature shortens the half-life", "Increasing pressure lengthens the half-life", "A chemical reaction shortens the half-life"],
      "Half-life is determined by the nucleus itself and is independent of physical conditions (temperature and pressure) and chemical state (element or compound)."),
    C("standard", "Which statement about half-life is correct?",
      "Half-life is the time for half the nuclei in a large sample to decay and is not meaningful for a small number of nuclei",
      ["Exactly 50 of 100 nuclei will remain after one half-life", "All nuclei decay after two half-lives", "A radioactive isotope's half-life shortens as its temperature rises"],
      "Half-life is a statistical law that applies only to large numbers of nuclei; it cannot predict when an individual nucleus will decay. After two half-lives, 1/4 remains, not zero."),
    N("advanced", "Radioactive isotopes A and B have half-lives of 2 days and 3 days, respectively. They start with equal numbers of nuclei. After 6 days, what is the ratio N_A/N_B of their remaining nuclei? (Enter the number only.)", "0.5",
      "In 6 days, A passes through 3 half-lives and N₀/8 remains; B passes through 2 half-lives and N₀/4 remains. Thus N_A/N_B = (1/8)/(1/4) = 0.5. Do not use the ratio of the half-lives directly.",
      "(1/2)**(6/2)/(1/2)**(6/3)"),
  ])

T("isotope_use", "Matter", "application",
  "Know applications of radioactive isotopes: use γ rays for flaw detection and treatment, use radiation penetration to measure thickness, use isotopes as tracers, and apply them in breeding and food preservation. Know that radiation harms the body and can be reduced by limiting exposure time, increasing distance, and using shielding. Understand how artificial radioisotopes are produced.",
  ["State the main applications of radioactive isotopes", "Explain the principle of tracer atoms", "Know the basic measures for radiation protection"],
  [("S3.3.3", "exact")],
  pre=[("half_life", "hard"), ("radioactivity", "hard")],
  qs=[
    C("basic", "Which type of radiation is used to inspect metal for internal cracks?",
      "γ rays", ["α rays", "β rays", "Ultraviolet light"],
      "γ rays have the greatest penetrating power and can pass through thick metal. A crack changes the amount of radiation transmitted, making γ rays useful for flaw detection; α and β rays penetrate less."),
    C("basic", "Which property allows a radioactive isotope to be used as a tracer?",
      "It has the same chemical properties as other isotopes of the element, and its radiation is easy to detect",
      ["It has an extremely long half-life and almost never decays", "Its radiation changes the chemical properties of other atoms", "Its mass is much greater than that of stable isotopes, making it easy to distinguish"],
      "Isotopes have the same chemical properties, so radioactive and stable isotopes behave alike in organisms and chemical reactions. Because the radioactive isotope emits detectable radiation, its path can be tracked."),
    C("standard", "Which is a reasonable radiation-protection measure when using a γ-ray source in a laboratory?",
      "Keep a large distance from the source, limit exposure time, and use thick lead shielding",
      ["Wrap the source in a thin plastic bag to block γ rays",
       "Heat the source so it decays faster and is no longer dangerous",
       "Work close to the source to finish quickly; distance does not affect the radiation dose"],
      "γ rays are highly penetrating and require shielding such as thick lead. Dose depends on distance and exposure time, so greater distance and shorter exposure are safer. Half-life is independent of temperature, so heating cannot make the source decay sooner."),
    N("standard", "A medical radioisotope has a half-life of 6 h. After an injection, it is considered safe only when its activity falls below 1/16 of its initial value. What is the minimum wait in hours? (Enter the number only.)", "24",
      "1/16 = (1/2)⁴, so 4 half-lives are needed: 4 × 6 h = 24 h. Activity is proportional to the number of undecayed nuclei, so N = N₀(½)^(t/τ) applies.",
      "6*4"),
  ])

T("binding_energy", "Matter", "procedural",
  "Know that the nuclear force is a short-range strong interaction acting over distances of about 10⁻¹⁵ m. The energy released when nucleons bind to form a nucleus is its binding energy. The energy released by a mass defect Δm is ΔE = Δmc², and 1 u corresponds to 931.5 MeV. A greater binding energy per nucleon means a more stable nucleus.",
  ["State the main properties of the nuclear force", "Calculate binding energy using ΔE = Δmc²", "Use binding energy per nucleon to assess nuclear stability"],
  [("S3.3.4", "exact"), ("S3.3.2", "exact")],
  pre=[("nucleus_comp", "hard"), ("relativity", "soft"), ("energy_law", "soft")],
  qs=[
    C("basic", "Which statement about the nuclear force is correct?",
      "The nuclear force is short-range and acts only over distances of about 10⁻¹⁵ m", ["The nuclear force is long-range and grows stronger with distance", "The nuclear force acts only between protons", "The nuclear force is the Coulomb force between protons"],
      "The nuclear force is a strong interaction with a range of only about 10⁻¹⁵ m. It acts between proton-proton, proton-neutron, and neutron-neutron pairs and is much stronger than the Coulomb force, binding positively charged protons in the nucleus."),
    N("basic", "A nuclear reaction has a mass defect of 0.02 u. If 1 u corresponds to 931.5 MeV of energy, how much nuclear energy is released, in MeV? (Enter the number only.)", "18.63",
      "ΔE = Δm × 931.5 MeV/u = 0.02 × 931.5 MeV = 18.63 MeV.",
      "round(0.02*931.5,2)"),
    N("standard", "A proton and a neutron combine to form a deuterium nucleus. The proton mass is 1.0073 u, the neutron mass is 1.0087 u, and the deuterium nucleus mass is 2.0136 u. If 1 u corresponds to 931.5 MeV, what is the deuterium nucleus's binding energy in MeV? (Round to two decimal places and enter the number only.)", "2.24",
      "The mass defect is Δm = 1.0073 + 1.0087 − 2.0136 = 0.0024 u, so the binding energy is ΔE = 0.0024 × 931.5 = 2.2356 MeV ≈ 2.24 MeV. The deuterium nucleus's binding energy per nucleon is about half this value.",
      "round((1.0073+1.0087-2.0136)*931.5,2)"),
    C("standard", "Which statement about binding energy and binding energy per nucleon is correct?",
      "The greater the binding energy per nucleon, the more tightly the nucleons are bound and the more stable the nucleus",
      ["A greater total binding energy always means a more stable nucleus", "Binding energy per nucleon is the total energy needed to separate a nucleus into individual nucleons", "A nucleus with a greater mass number must have greater binding energy per nucleon"],
      "Binding energy per nucleon is the binding energy divided by the number of nucleons and indicates nuclear stability; a greater value means greater stability. Binding energy is the total energy needed to separate a nucleus, so nuclei with more nucleons have greater total binding energy but are not necessarily more stable. Medium-mass nuclei have the greatest binding energy per nucleon."),
  ])

T("fission_fusion", "Matter", "conceptual",
  "Know that heavy nuclei can fission (for example, uranium-235 absorbs a neutron, splits, and releases neutrons), and understand chain reactions, critical size, and the basic principle of a nuclear reactor. Know the equation and conditions for light-nucleus fusion (very high temperatures are needed to overcome Coulomb repulsion), and estimate the energy released by nuclear reactions.",
  ["Distinguish equations for fission, fusion, decay, and artificial transmutation", "State the conditions for a chain reaction", "Estimate the energy released by fission"],
  [("S3.3.4", "exact")],
  pre=[("binding_energy", "hard"), ("decay", "hard"), ("J:new_energy", "soft")],
  qs=[
    C("basic", "Which of the following nuclear equations describes heavy-nucleus fission?",
      "²³⁵₉₂U + ¹₀n → ¹⁴⁴₅₆Ba + ⁸⁹₃₆Kr + 3¹₀n",
      ["²₁H + ³₁H → ⁴₂He + ¹₀n", "²³⁸₉₂U → ²³⁴₉₀Th + ⁴₂He", "¹⁴₇N + ⁴₂He → ¹⁷₈O + ¹₁H"],
      "The deuterium-tritium reaction that forms helium is light-nucleus fusion; uranium-238 emitting a helium nucleus is α decay; and nitrogen reacting with an α particle is the artificial transmutation through which Rutherford discovered the proton. Heavy-nucleus fission occurs when a heavy nucleus absorbs a neutron, splits into two medium-mass nuclei, and releases neutrons."),
    C("basic", "Neutrons released by uranium-235 fission can cause other uranium nuclei to fission, sustaining the reaction; this is a chain reaction. What condition must a uranium mass meet for the chain reaction to continue?",
      "Its volume must be at least the critical volume", ["Its volume must be below the critical volume", "A smaller volume makes the reaction easier", "It must be continuously bombarded with high-speed electrons"],
      "When the uranium mass is too small, most neutrons released by fission escape from its surface and cannot trigger more fissions. The chain reaction continues only when the volume is at least the critical volume."),
    C("standard", "Why must light-nucleus fusion occur at an extremely high temperature?",
      "The nuclei need enough kinetic energy to overcome Coulomb repulsion and approach within the range of the nuclear force",
      ["The nuclei must overcome the attractive nuclear force and separate", "The fusion reactants must melt into a liquid", "The electrons outside the nucleus must gain enough energy to leave the atoms"],
      "Light nuclei are positively charged and strongly repel one another. Only at temperatures of several million kelvin or more do they have enough kinetic energy to approach within about 10⁻¹⁵ m, where the nuclear force can act and bind them."),
    N("advanced", "Each uranium-235 nucleus releases about 200 MeV of energy when it fissions. 1 MeV = 1.6×10⁻¹³ J. If 235 g of uranium-235 (6.0×10²³ nuclei) all fission, how much total energy is released, in units of 10¹³ J? (Enter the number only.)", "1.92",
      "Each nucleus releases 200 MeV = 3.2×10⁻¹¹ J. The total is E = 6.0×10²³ × 3.2×10⁻¹¹ J = 1.92×10¹³ J, equivalent to the energy released by burning about 650 metric tons of standard coal. Do not omit the conversion from MeV to J.",
      "round(6.0e23*200*1.6e-13/1e13,2)"),
  ])

T("particles", "Matter", "conceptual",
  "Know the four fundamental interactions in nature: gravity, electromagnetism, the strong interaction, and the weak interaction. Know that particles are classified as hadrons, leptons, and gauge bosons; hadrons are made of quarks, which carry fractional charges. Appreciate how human understanding of matter's structure has developed through exploration.",
  ["Name the four fundamental interactions and describe their roles", "Classify common particles", "Calculate a particle's charge from its quark content"],
  [("S3.3.5", "exact"), ("S3.3.2", "exact")],
  pre=[("nucleus_comp", "hard"), ("gravitation", "soft"), ("binding_energy", "soft")],
  qs=[
    C("basic", "Which interaction binds nucleons together and keeps the nucleus stable?",
      "The strong interaction", ["The electromagnetic interaction", "Gravity", "The weak interaction"],
      "The nuclear force is the strong interaction, much stronger than the Coulomb repulsion between nucleons. The weak interaction is involved in processes such as β decay, while gravity is extremely weak at the microscopic scale."),
    C("basic", "Which of the four fundamental interactions is the weakest?",
      "Gravity", ["The weak interaction", "The electromagnetic interaction", "The strong interaction"],
      "Their approximate strengths rank as strong > electromagnetic > weak > gravity. Despite its name, the weak interaction is not the weakest; gravity between microscopic particles is nearly negligible."),
    C("standard", "Which of the following particles is a lepton?",
      "Electron", ["Proton", "Neutron", "Quark"],
      "Electrons and neutrinos are leptons because they do not participate in the strong interaction. Protons and neutrons are hadrons that participate in the strong interaction and are made of quarks; quarks are not leptons."),
    C("standard", "An up quark has charge +2e/3 and a down quark has charge −e/3. What is the charge of a particle (a neutron) made of one up quark and two down quarks?",
      "0", ["+e", "−e", "+e/3"],
      "The total charge is 2e/3 + 2×(−e/3) = 0, so the neutron is neutral. A proton contains two up quarks and one down quark: 2×(2e/3) − e/3 = +e."),
  ])
